    // profilealloc resets the current mcache's nextSample counter and
    // records a memory profile sample.
    //
    // The caller must be non-preemptible and have a P.
    void profilealloc(m* mp, gocpp::unsafe_pointer x, uintptr_t size)
    {
        auto c = getMCache(mp);
        if(c == nullptr)
        {
            go_throw("profilealloc called without a P or outside bootstrapping"_s);
        }
        c->memProfRate = MemProfileRate;
        c->nextSample = nextSample();
        mProf_Malloc(mp, x, size);
    }

    // nextSample returns the next sampling point for heap profiling. The goal is
    // to sample allocations on average every MemProfileRate bytes, but with a
    // completely random distribution over the allocation timeline; this
    // corresponds to a Poisson process with parameter MemProfileRate. In Poisson
    // processes, the distance between two samples follows the exponential
    // distribution (exp(MemProfileRate)), so the best return value is a random
    // number taken from an exponential distribution whose mean is MemProfileRate.
    int64_t nextSample()
    {
        if(MemProfileRate == 0)
        {
            // Basically never sample.
            return math::MaxInt64;
        }
        if(MemProfileRate == 1)
        {
            // Sample immediately.
            return 0;
        }
        return int64_t(fastexprand(MemProfileRate));
    }

    // fastexprand returns a random number from an exponential distribution with
    // the specified mean.
    int32_t fastexprand(int mean)
    {
        // Avoid overflow. Maximum possible step is
        // -ln(1/(1<<randomBitCount)) * mean, approximately 20 * mean.
        //Go switch emulation
        {
            int conditionId = -1;
            if(mean > 0x7000000) { conditionId = 0; }
            else if(mean == 0) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    mean = 0x7000000;
                    break;
                case 1:
                    return 0;
                    break;
            }
        }

        // Take a random sample of the exponential distribution exp(-mean*x).
        // The probability distribution function is mean*exp(-mean*x), so the CDF is
        // p = 1 - exp(-mean*x), so
        // q = 1 - p == exp(-mean*x)
        // log_e(q) = -mean*x
        // -log_e(q)/mean = x
        // x = -log_e(q) * mean
        // x = log_2(q) * (-log_e(2)) * mean    ; Using log_2 for efficiency
        auto randomBitCount = 26;
        auto q = cheaprandn(1 << randomBitCount) + 1;
        auto qlog = fastlog2(double(q)) - randomBitCount;
        if(qlog > 0)
        {
            qlog = 0;
        }
        // -ln(2)
        auto minusLog2 = - 0.6931471805599453;
        return int32_t(qlog * (minusLog2 * double(mean))) + 1;
    }

    
