    globalAllocStruct globalAlloc;
    // persistentChunks is a list of all the persistent chunks we have
    // allocated. The list is maintained through the first word in the
    // persistent chunk. This is updated atomically.
    notInHeap* persistentChunks;
    // Wrapper around sysAlloc that can allocate small chunks.
    // There is no associated free operation.
    // Intended for things like function/type/debug-related persistent data.
    // If align is 0, uses default align (currently 8).
    // The returned memory will be zeroed.
    // sysStat must be non-nil.
    //
    // Consider marking persistentalloc'd types not in heap by embedding
    // internal/runtime/sys.NotInHeap.
    //
    // nosplit because it is used during write barriers and must not be preempted.
    //
    //go:nosplit
    gocpp::unsafe_pointer persistentalloc(uintptr_t size, uintptr_t align, sysMemStat* sysStat)
    {
        notInHeap* p = {};
        systemstack([=]() mutable -> void
        {
            p = persistentalloc1(size, align, sysStat);
        });
        return gocpp::unsafe_pointer(p);
    }

    // Must run on system stack because stack growth can (re)invoke it.
    // See issue 9174.
    //
    //go:systemstack
    notInHeap* persistentalloc1(uintptr_t size, uintptr_t align, sysMemStat* sysStat)
    {
        auto maxBlock = 64 << 10;

        if(size == 0)
        {
            go_throw("persistentalloc: size == 0"_s);
        }
        if(align != 0)
        {
            if(align & (align - 1) != 0)
            {
                go_throw("persistentalloc: align is not a power of 2"_s);
            }
            if(align > pageSize)
            {
                go_throw("persistentalloc: align is too large"_s);
            }
        }
        else
        {
            align = 8;
        }

        if(size >= maxBlock)
        {
            return (notInHeap*)(sysAlloc(size, sysStat, "immortal metadata"_s));
        }

        auto mp = acquirem();
        persistentAlloc* persistent = {};
        if(mp != nullptr && mp->p != 0)
        {
            persistent = & rec::ptr(gocpp::recv(mp->p))->palloc;
        }
        else
        {
            lock(& globalAlloc.mutex);
            persistent = & globalAlloc.persistentAlloc;
        }
        persistent->off = alignUp(persistent->off, align);
        if(persistent->off + size > persistentChunkSize || persistent->base == nullptr)
        {
            persistent->base = (notInHeap*)(sysAlloc(persistentChunkSize, & memstats.other_sys, "immortal metadata"_s));
            if(persistent->base == nullptr)
            {
                if(persistent == & globalAlloc.persistentAlloc)
                {
                    unlock(& globalAlloc.mutex);
                }
                go_throw("runtime: cannot allocate memory"_s);
            }

            // Add the new chunk to the persistentChunks list.
            for(; ; )
            {
                auto chunks = uintptr_t(gocpp::unsafe_pointer(persistentChunks));
                *(uintptr_t*)(gocpp::unsafe_pointer(persistent->base)) = chunks;
                if(atomic::Casuintptr((uintptr_t*)(gocpp::unsafe_pointer(& persistentChunks)), chunks, uintptr_t(gocpp::unsafe_pointer(persistent->base))))
                {
                    break;
                }
            }
            persistent->off = alignUp(goarch::PtrSize, align);
        }
        auto p = rec::add(gocpp::recv(persistent->base), persistent->off);
        persistent->off += size;
        releasem(mp);
        if(persistent == & globalAlloc.persistentAlloc)
        {
            unlock(& globalAlloc.mutex);
        }

        if(sysStat != & memstats.other_sys)
        {
            rec::add(gocpp::recv(sysStat), int64_t(size));
            rec::add(gocpp::recv(memstats.other_sys), - int64_t(size));
        }
        return p;
    }

    // inPersistentAlloc reports whether p points to memory allocated by
    // persistentalloc. This must be nosplit because it is called by the
    // cgo checker code, which is called by the write barrier code.
    //
    //go:nosplit
    bool inPersistentAlloc(uintptr_t p)
    {
        auto chunk = atomic::Loaduintptr((uintptr_t*)(gocpp::unsafe_pointer(& persistentChunks)));
        for(; chunk != 0; )
        {
            if(p >= chunk && p < chunk + persistentChunkSize)
            {
                return true;
            }
            chunk = *(uintptr_t*)(gocpp::unsafe_pointer(chunk));
        }
        return false;
    }

    // linearAlloc is a simple linear allocator that pre-reserves a region
    // of memory and then optionally maps that region into the Ready state
    // as needed.
    //
    // The caller is responsible for locking.
    
    template<typename T> requires gocpp::GoStruct<T>
    linearAlloc::operator T()
    {
        T result;
        result.next = this->next;
        result.mapped = this->mapped;
        result.end = this->end;
        result.mapMemory = this->mapMemory;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool linearAlloc::operator==(const T& ref) const
    {
        if (next != ref.next) return false;
        if (mapped != ref.mapped) return false;
        if (end != ref.end) return false;
        if (mapMemory != ref.mapMemory) return false;
        return true;
    }

    std::ostream& linearAlloc::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << next;
        os << " " << mapped;
        os << " " << end;
        os << " " << mapMemory;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct linearAlloc& value)
    {
        return value.PrintTo(os);
    }

    void rec::init(linearAlloc* l, uintptr_t base, uintptr_t size, bool mapMemory)
    {
        if(base + size < base)
        {
            // Chop off the last byte. The runtime isn't prepared
            // to deal with situations where the bounds could overflow.
            // Leave that memory reserved, though, so we don't map it
            // later.
            size -= 1;
        }
        std::tie(l->next, l->mapped) = std::tuple{base, base};
        l->end = base + size;
        l->mapMemory = mapMemory;
    }

    gocpp::unsafe_pointer rec::alloc(linearAlloc* l, uintptr_t size, uintptr_t align, sysMemStat* sysStat, gocpp::string vmaName)
    {
        auto p = alignUp(l->next, align);
        if(p + size > l->end)
        {
            return nullptr;
        }
        l->next = p + size;
        if(auto pEnd = alignUp(l->next - 1, physPageSize); pEnd > l->mapped)
        {
            if(l->mapMemory)
            {
                // Transition from Reserved to Prepared to Ready.
                auto n = pEnd - l->mapped;
                sysMap(gocpp::unsafe_pointer(l->mapped), n, sysStat, vmaName);
                sysUsed(gocpp::unsafe_pointer(l->mapped), n, n);
            }
            l->mapped = pEnd;
        }
        return gocpp::unsafe_pointer(p);
    }

    // notInHeap is off-heap memory allocated by a lower-level allocator
    // like sysAlloc or persistentAlloc.
    //
    // In general, it's better to use real types which embed
    // internal/runtime/sys.NotInHeap, but this serves as a generic type
    // for situations where that isn't possible (like in the allocators).
    //
    // TODO: Use this as the return type of sysAlloc, persistentAlloc, etc?
    
    template<typename T> requires gocpp::GoStruct<T>
    notInHeap::operator T()
    {
        T result;
        result._1 = this->_1;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool notInHeap::operator==(const T& ref) const
    {
        if (_1 != ref._1) return false;
        return true;
    }

