    notInHeap* rec::add(notInHeap* p, uintptr_t bytes)
    {
        return (notInHeap*)(gocpp::unsafe_pointer(uintptr_t(gocpp::unsafe_pointer(p)) + bytes));
    }

    // redZoneSize computes the size of the redzone for a given allocation.
    // Refer to the implementation of the compiler-rt.
    uintptr_t redZoneSize(uintptr_t userSize)
    {
        //Go switch emulation
        {
            int conditionId = -1;
            if(userSize <= (64 - 16)) { conditionId = 0; }
            else if(userSize <= (128 - 32)) { conditionId = 1; }
            else if(userSize <= (512 - 64)) { conditionId = 2; }
            else if(userSize <= (4096 - 128)) { conditionId = 3; }
            else if(userSize <= (1 << 14) - 256) { conditionId = 4; }
            else if(userSize <= (1 << 15) - 512) { conditionId = 5; }
            else if(userSize <= (1 << 16) - 1024) { conditionId = 6; }
            switch(conditionId)
            {
                case 0:
                    return 16 << 0;
                    break;
                case 1:
                    return 16 << 1;
                    break;
                case 2:
                    return 16 << 2;
                    break;
                case 3:
                    return 16 << 3;
                    break;
                case 4:
                    return 16 << 4;
                    break;
                case 5:
                    return 16 << 5;
                    break;
                case 6:
                    return 16 << 6;
                    break;
                default:
                    return 16 << 7;
                    break;
            }
        }
    }

